api_key = os.environ['DAYTONA_API_KEY']
current_sandbox = os.environ.get('DAYTONA_SANDBOX_ID', '')

# List sandboxes
req = urllib.request.Request(
    'https://app.daytona.io/api/sandbox',
    headers={
        'Authorization': 'Bearer ' + api_key,
        'Content-Type': 'application/json'
    }
)
with urllib.request.urlopen(req) as resp:
    data = json.loads(resp.read())
    items = data.get('items', [])
    print('Found', len(items), 'sandboxes')

    for item in items:
        sandbox_id = item['id']
        if sandbox_id == current_sandbox:
            print('Skipping current sandbox:', sandbox_id)
            continue
        print('Deleting sandbox:', sandbox_id)
        del_req = urllib.request.Request(
            'https://app.daytona.io/api/sandbox/' + sandbox_id,
            headers={
                'Authorization': 'Bearer ' + api_key,
                'Content-Type': 'application/json'
            },
            method='DELETE'
        )
